MIGRATIONS = [
    ("001_create_ledger", "CREATE TABLE IF NOT EXISTS ledger (id INTEGER PRIMARY KEY, amount_cents INTEGER NOT NULL);"),
    ("002_add_currency", "ALTER TABLE ledger ADD COLUMN currency TEXT NOT NULL DEFAULT 'USD';"),
]


def applied_migrations(connection):
    exists = connection.execute(
        "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'schema_migrations'"
    ).fetchone()
    if exists is None:
        return set()
    return {row[0] for row in connection.execute("SELECT name FROM schema_migrations")}


