        "CREATE TABLE IF NOT EXISTS schema_migrations (name TEXT PRIMARY KEY)"
    )
    applied = applied_migrations(connection)
    for name, sql in MIGRATIONS:
        if name in applied:
            continue
        connection.execute(sql)
        connection.execute(
            "INSERT INTO schema_migrations (name) VALUES (?)", (name,)
        )
