STAMP = re.compile(r"^\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\]\s+(.*)$")


def parse_lines(lines):
    rows = []
    for raw in lines:
        line = raw.rstrip("\r\n")
        match = STAMP.match(line)
        rows.append({
            "timestamp": match.group(1),
            "message": match.group(2),
