from pathlib import Path

def rotate_backups(directory, keep=2):
    backups = sorted(
        Path(directory).glob("*.tgz"),
        key=lambda backup: backup.stat().st_mtime,
        reverse=True,
    )
    excess = max(0, len(backups) - keep)
    for backup in backups[:excess]:
        backup.unlink()

